#!/usr/bin/env python3
"""Cross-reference tool identifiers used in docs/ and examples/ against work/02-research.md.

Usage: xref.py <repo_root> <out_json>
Extracts code-formatted identifiers (flags, settings keys, env vars, IAM condition keys,
snake_case keywords, permission-rule tools) from Markdown, plus config keys from the
example JSON/YAML files. For each term reports where a source exists.
"""
import collections
import glob
import json
import os
import re
import subprocess
import sys

root, out = sys.argv[1], sys.argv[2]
os.chdir(root)
tracked = subprocess.check_output(["git", "ls-files"], text=True).split()

R02 = open("work/02-research.md", encoding="utf-8").read()
OTHER = {p: open(p, encoding="utf-8").read() for p in
         ["work/09-fix-research.md", "work/07-review.md", "work/08-fix-proposals.md",
          "work/03-options.md", "work/01-problem-framing.md", "work/05-deliverable-plan.md"]}
SCHEMA = {p: open(p, encoding="utf-8").read() for p in glob.glob("examples/schemas/*.json")}
TESTMAP = open("examples/tests/test_claude_settings.py", encoding="utf-8").read()

terms = collections.defaultdict(lambda: {"cat": None, "uses": []})


def add(term, cat, where):
    t = terms[term]
    t["cat"] = t["cat"] or cat
